const db = new Store("farm-log");
app.innerHTML = "<div class='card' id='form'></div><div id='list'></div>";
const FIELDS = [
  { name: "date", label: "Date", type: "date", required: true },
  { name: "crop", label: "Crop", type: "choice", choices: ["maize", "beans", "kale"], required: true },
  { name: "kg", label: "Kg", type: "number", min: 0, required: true },
];
makeForm(document.getElementById("form"), FIELDS, (v) => { db.add("harvest", v); render(); });

function render() {
  makeTable(document.getElementById("list"), [
    { key: "date", label: "Date" }, { key: "crop", label: "Crop" }, { key: "kg", label: "Kg", num: true }],
    { totals: ["kg"] }).show(db.list("harvest"));
}
render();

app.insertAdjacentHTML("beforeend", "<button id='csv'>Export</button> <button id='bk'>Backup</button>");
document.getElementById("csv").onclick = () => downloadCSV("harvests.csv", db.list("harvest"));
document.getElementById("bk").onclick = () => db.exportFile();

T.add({ en: { crop: "Crop", kg: "Kg" }, sw: { crop: "Zao", kg: "Kilo" } });
// labels: label: T("crop") ...
addAccessButtons(document.querySelector(".bar"));
